actions.script:
import java.util.Base64
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper

def targetUserId = userId

// If no userId provided, extract from JWT token
if (!targetUserId && ec.web?.request) {
    def authHeader = ec.web.request.getHeader("Authorization")
    if (authHeader && authHeader.startsWith("Bearer ")) {
        def jwtToken = authHeader.substring(7)
        try {
            def parts = jwtToken.split('\\.')
            if (parts.length == 3) {
                def payloadJson = new String(Base64.urlDecoder.decode(parts[1]), StandardCharsets.UTF_8)
                def payload = new JsonSlurper().parseText(payloadJson)
                targetUserId = payload.sub
            }
        } catch (Exception e) {
            ec.logger.warn("Failed to extract userId from token", e)
        }
    }
}

if (!targetUserId) {
    success = false
    message = "User ID not provided and could not be extracted from token."
    errorCode = "NO_USER_ID"
    return
}

try {
    // Get user record to check credits balance
    def userRecord = ec.entity.find("novel.anime.user.NovelAnimeUser")
        .condition("userId", targetUserId)
        .disableAuthz()
        .one()

    if (!userRecord) {
        success = false
        message = "User not found."
        errorCode = "USER_NOT_FOUND"
        return
    }

    if (userRecord.status != 'active') {
        success = false
        message = "User account is not active."
        errorCode = "ACCOUNT_INACTIVE"
        return
    }

    // Return current credits balance (Requirement 3.1)
    balance = userRecord.credits ?: 0

    // Check if credits are low (< 50) (Requirement 3.3)
    isLow = balance < 50

    success = true
    message = "Credits balance retrieved successfully."

    ec.logger.info("Credits balance retrieved for user ${targetUserId}: ${balance}")

} catch (Exception e) {
    ec.logger.error("Failed to get credits balance for user ${targetUserId}", e)
    success = false
    message = "Failed to retrieve credits balance: " + e.message
    errorCode = "BALANCE_ERROR"
}

import java.util.Base64
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper

def targetUserId = userId

// If no userId provided, extract from JWT token
if (!targetUserId && ec.web?.request) {
    def authHeader = ec.web.request.getHeader("Authorization")
    if (authHeader && authHeader.startsWith("Bearer ")) {
        def jwtToken = authHeader.substring(7)
        try {
            def parts = jwtToken.split('\\.')
            if (parts.length == 3) {
                def payloadJson = new String(Base64.urlDecoder.decode(parts[1]), StandardCharsets.UTF_8)
                def payload = new JsonSlurper().parseText(payloadJson)
                targetUserId = payload.sub
            }
        } catch (Exception e) {
            ec.logger.warn("Failed to extract userId from token", e)
        }
    }
}

if (!targetUserId) {
    success = false
    message = "User ID not provided and could not be extracted from token."
    errorCode = "NO_USER_ID"
    return
}

// Validate amount
if (!amount || amount <= 0) {
    success = false
    message = "Amount must be a positive integer."
    errorCode = "INVALID_AMOUNT"
    return
}

try {
    // Use transaction to ensure atomicity (Requirement 8.3 - rollback on failure)
    ec.transaction.begin()

    // Get user record with FOR UPDATE lock to prevent race conditions
    def userRecord = ec.entity.find("novel.anime.user.NovelAnimeUser")
        .condition("userId", targetUserId)
        .forUpdate(true)
        .disableAuthz()
        .one()

    if (!userRecord) {
        ec.transaction.rollback()
        success = false
        message = "User not found."
        errorCode = "USER_NOT_FOUND"
        return
    }

    if (userRecord.status != 'active') {
        ec.transaction.rollback()
        success = false
        message = "User account is not active."
        errorCode = "ACCOUNT_INACTIVE"
        return
    }

    def currentBalance = userRecord.credits ?: 0

    // Check sufficient balance before deduction (Requirement 4.1, 4.2)
    if (currentBalance < amount) {
        ec.transaction.rollback()
        success = false
        message = "Insufficient credits. Required: ${amount}, Available: ${currentBalance}"
        errorCode = "INSUFFICIENT_CREDITS"
        return
    }

    // Deduct credits atomically (Requirement 4.3)
    newBalance = currentBalance - amount
    userRecord.credits = newBalance
    userRecord.update()

    // Record transaction with all required fields (Requirement 8.1)
    def now = ec.user.nowTimestamp
    transactionId = ec.entity.sequencedIdPrimary
    def transactionDescription = description ?: "Credits consumed for ${operationType}"

    ec.entity.makeValue("novel.anime.user.CreditTransaction").setAll([
        transactionId: transactionId,
        userId: targetUserId,
        amount: (0 - amount), // Negative for consumption
        type: 'consume',
        operationType: operationType,
        description: transactionDescription,
        balanceAfter: newBalance,
        timestamp: now
    ]).create()

    ec.transaction.commit()

    success = true
    message = "Credits consumed successfully. New balance: ${newBalance}"

    ec.logger.info("Credits consumed for user ${targetUserId}: ${amount} credits for ${operationType}, new balance: ${newBalance}")

} catch (Exception e) {
    ec.transaction.rollback()
    ec.logger.error("Failed to consume credits for user ${targetUserId}", e)
    success = false
    message = "Failed to consume credits: " + e.message
    errorCode = "CONSUME_ERROR"
}

import java.util.Base64
import java.nio.charset.StandardCharsets
import groovy.json.JsonSlurper

def targetUserId = userId

// If no userId provided, extract from JWT token
if (!targetUserId && ec.web?.request) {
    def authHeader = ec.web.request.getHeader("Authorization")
    if (authHeader && authHeader.startsWith("Bearer ")) {
        def jwtToken = authHeader.substring(7)
        try {
            def parts = jwtToken.split('\\.')
            if (parts.length == 3) {
                def payloadJson = new String(Base64.urlDecoder.decode(parts[1]), StandardCharsets.UTF_8)
                def payload = new JsonSlurper().parseText(payloadJson)
                targetUserId = payload.sub
            }
        } catch (Exception e) {
            ec.logger.warn("Failed to extract userId from token", e)
        }
    }
}

if (!targetUserId) {
    success = false
    message = "User ID not provided and could not be extracted from token."
    errorCode = "NO_USER_ID"
    return
}

// Validate pagination parameters
def currentPage = page ?: 1
def currentPageSize = pageSize ?: 20

if (currentPage < 1) currentPage = 1
if (currentPageSize < 1) currentPageSize = 20
if (currentPageSize > 100) currentPageSize = 100

try {
    // Verify user exists
    def userRecord = ec.entity.find("novel.anime.user.NovelAnimeUser")
        .condition("userId", targetUserId)
        .disableAuthz()
        .one()

    if (!userRecord) {
        success = false
        message = "User not found."
        errorCode = "USER_NOT_FOUND"
        return
    }

    // Build query for transaction history
    def transactionQuery = ec.entity.find("novel.anime.user.CreditTransaction")
        .condition("userId", targetUserId)
        .disableAuthz()

    // Apply type filter if provided (Requirement 3.4 - filtering by type)
    if (type) {
        transactionQuery.condition("type", type)
    }

    // Get total count for pagination
    totalCount = transactionQuery.count()

    // Calculate pagination
    totalPages = Math.ceil(totalCount / currentPageSize) as Integer
    def offset = (currentPage - 1) * currentPageSize

    // Get paginated results ordered by timestamp descending (most recent first)
    def orderByField = "-timestamp"
    def transactionRecords = transactionQuery
        .orderBy(orderByField)
        .offset(offset)
        .limit(currentPageSize)
        .list()

    // Build response list (Requirement 8.2 - paginated transaction records)
    transactions = []
    transactionRecords.each { record ->
        transactions.add([
            transactionId: record.transactionId,
            amount: record.amount,
            type: record.type,
            operationType: record.operationType,
            description: record.description,
            balanceAfter: record.balanceAfter,
            timestamp: record.timestamp?.toString()
        ])
    }

    page = currentPage
    pageSize = currentPageSize
    success = true
    message = "Credits history retrieved successfully."

    ec.logger.info("Credits history retrieved for user ${targetUserId}: ${transactions.size()} records (page ${currentPage}/${totalPages})")

} catch (Exception e) {
    ec.logger.error("Failed to get credits history for user ${targetUserId}", e)
    success = false
    message = "Failed to retrieve credits history: " + e.message
    errorCode = "HISTORY_ERROR"
}
